import {View, Text, TouchableOpacity} from 'react-native';
import Animated, {
  FadeInUp,
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from 'react-native-reanimated';
import {styles} from './styles';
import TextCM from '../../../components/Text';
import {TaskGroup} from '../../../../model/interface/dashboard.interface';
import {useState} from 'react';
import TableTaskCard from './TableTaskCard';
import {Font} from '../../../../constants';

type Props = {
  listTask?: TaskGroup[];
  title?: string | React.ReactNode;
};
export default function DashboardTaskList({listTask, title}: Props) {
  const [isExpanded, setIsExpanded] = useState(false);
  const rotation = useSharedValue(0);
  const toggleExpand = () => {
    setIsExpanded(!isExpanded);
    rotation.value = withTiming(isExpanded ? 0 : 90, {duration: 300});
  };
  const animatedStyle = useAnimatedStyle(() => {
    return {
      transform: [{rotate: `${rotation.value}deg`}],
    };
  });
  return (
    <View style={styles.container}>
      {title && (
        <TextCM style={{fontSize: 18, fontFamily: Font.InterBold700}}>
          {title}
        </TextCM>
      )}

      {listTask?.map(item => {
        return <TableTaskCard item={item} key={item.listTaskId} />;
      })}
    </View>
  );
}
